from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    extracted_groups = []  # Step 2: Initialize an empty list to store the extracted groups
    nesting_level = 0
    current_group = ""

    for char in paren_string:  # Step 3: Iterate through the input string character by character
        if char == "(":
            nesting_level += 1
            if nesting_level > 1:
                current_group += char
        elif char == ")":
            nesting_level -= 1
            if nesting_level > 0:
                current_group += char
            elif nesting_level == 0:
                extracted_groups.append(current_group)
                current_group = ""

    return extracted_groups  # Step 8: Return the list of extracted groups

